head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _2 : mergeOptionStr = bycolrec / byrowrec (재귀 2차 병합). description 은 _1 과 동일.
scwin.tData = {
    "description" : "[gridView > M > mergeCells]<br/>GridView 컴포넌트의 mergeCells 속성을 설정합니다.",
    "validation" : [
        "mergeOptionStr 'bycolrec' 설정 시 'bycol' 방식으로 병합 후 'byrow' 방식으로 2차 병합을 수행합니다.",
        "mergeOptionStr 'byrowrec' 설정 시 'byrow' 방식으로 병합 후 'bycol' 방식으로 2차 병합을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 재귀 병합(2차) 차이가 드러나도록 구성. (P_2 와 동일한 2x2 블록 데이터)
//  fixedRow/fixedColumn 없음, col1~col4 단순 4행.
//  · 2x2 블록 4개 : (col1,col2 × row0,row1)=A, (col3,col4 × row0,row1)=C, (col1,col2 × row2,row3)=B, (col3,col4 × row2,row3)=D
//
//  행 | col1 | col2 | col3 | col4
//  ---+------+------+------+------
//   0 |  A   |  A   |  C   |  C
//   1 |  A   |  A   |  C   |  C
//   2 |  B   |  B   |  D   |  D
//   3 |  B   |  B   |  D   |  D
//
//  · bycolrec : 'bycol'(세로) 후 'byrow'(가로) 2차 병합 → 각 블록이 rowSpan2 + colSpan2 블록병합
//  · byrowrec : 'byrow'(가로) 후 'bycol'(세로) 2차 병합 → 각 블록이 rowSpan2 + colSpan2 블록병합
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
    { "col1": "A", "col2": "A", "col3": "C", "col4": "C" },
    { "col1": "B", "col2": "B", "col3": "D", "col4": "D" },
    { "col1": "B", "col2": "B", "col3": "D", "col4": "D" }
];



// comp 생성 : col1~col4 단순 4행 그리드 1개를 동적 생성한다. (P_2 와 동일 구성)
//  ★ mergeCells 속성은 생성 attribute 로 주지 않는다. (초기 미병합 상태로 생성 후 mergeCells() 메소드로 적용)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="2x2 블록 4개 : (col1,col2 × row0,row1)=A, (col3,col4 × row0,row1)=C, (col1,col2 × row2,row3)=B, (col3,col4 × row2,row3)=D. par_mergeOptionStr 선택 후 mergeCells 버튼으로 적용"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // col1~col4 단순 dataList (fixedRow/fixedColumn 없음)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="34" id="" style="width:560px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCells sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCells 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCells(mergeOptionStr) 호출
//  · options(선택) 파라미터는 _5(options 전용) 샘플에서 다루므로 여기서는 생략한다.
scwin.btn_mergeCells_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCells(mode);

    bottom.setReturnValue("[옵션] mergeCells=" + target1.options.mergeCells + " / mergeOptionStr='" + mode + "'");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로(⬇)/가로(➡)/블록(⬛) 병합 그룹을 출력
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "병합 없음";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "세로(rowSpan) 병합";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "가로(colSpan) 병합";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
}
